// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _test(address ownerAddr) internal {
        vm.assume(ownerAddr != address(0));
        vm.assume(address(c).balance > 0);
        vm.assume(c.Owner() == address(this));
        uint balBefore = address(c).balance;
        try c.withdraw() {} catch { return; }
        assertTrue(address(c).balance == 0);
    }

    function testFuzz_test(address ownerAddr) public {
        vm.assume(uint160(ownerAddr) > 255 && ownerAddr != address(this) && ownerAddr != address(c) && ownerAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && ownerAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && ownerAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && ownerAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(ownerAddr);
    }

    receive() external payable {}
}
